58	 /* ============================ Lái xe: va chạm thân xe nhiều tầng ============================
59	    Thân xe là hình chữ nhật có hướng (dài × rộng VF 3), tâm ở giữa hai trục bánh, cao độ p.y là mặt đường tại tâm.
60	    - Thân xe hợp lệ khi 9 điểm mẫu (4 góc, 4 trung điểm cạnh, tâm) đều có mặt đường cùng tầng (drGround hữu hạn từ yRef = p.y),
61	      không chồng vật cản nào có khoảng cao độ giao [y + sim.floor, y + chiều cao xe], không chồng hộp xe tự động cùng tầng (trừ hộp bỏ qua).
62	    - Luật xe tự động (spec §6): đầu mỗi drMove, hộp nào đã chồng tư thế xuất phát thì bỏ qua cả lượt đó; nhờ vậy xe tự động đâm tới
63	      thì đi xuyên, người chơi tự lao vào thì bị chặn, đã chồng thì vẫn lái ra được theo mọi hướng.
64	+   - Đường thoát: tư thế đầu lượt đã chồng vật cản tĩnh hoặc ra ngoài ô thì nhận bước con không làm tệ hơn (drBad), để không kẹt vĩnh viễn.
65	    - Vật cản tra qua chỉ mục lưới ô DRC m (mẫu stroll/map.ts), giữ ngoài DrNet trong một WeakMap; dựng lười, nối thêm khi drAddSolids
66	      push vật cản mới, dựng lại khi mảng bị thay. Vật cản phủ quá nhiều ô để riêng danh sách "lớn", tra tuyến tính.
67	    - drFits / drMove / drSegClear chạy mỗi khung: không cấp phát (D-018), trừ khi lưới nối thêm vật cản hoặc mảng bỏ qua phải nới.
68	    Quy ước hướng: yaw = 0 mũi xe hướng +X; vectơ tiến (cos yaw, −sin yaw); dyaw > 0 là rẽ trái khi tiến. */
69	 import { CONFIG } from '../../config';
70	 import { drGround, type DrNet, type DrSolid } from './net';
71	 
72	 export interface DrPose { x: number; y: number; z: number; yaw: number }
73	 export interface DrBox { x: number; y: number; z: number; yaw: number; hl: number; hw: number }   // hộp xe tự động: nửa dài, nửa rộng
74	 
75	@@ -58,20 +59,35 @@ function drHitSolid(sol: DrSolid, x: number, z: number, c: number, s: number): b
76	     const ex = x + lf * c + ln * s - sol.cx, ez = z - lf * s + ln * c - sol.cz;
77	     return ex * ex + ez * ez < sol.r * sol.r - EPS;
78	   }
79	   const ex = (sol.x1 - sol.x0) / 2, ez = (sol.z1 - sol.z0) / 2, dx = (sol.x0 + sol.x1) / 2 - x, dz = (sol.z0 + sol.z1) / 2 - z;
80	   if (Math.abs(dx) >= ex + HL * ac + HW * as - EPS) return false;    // tách theo trục X
81	   if (Math.abs(dz) >= ez + HL * as + HW * ac - EPS) return false;    // trục Z
82	   if (Math.abs(dx * c - dz * s) >= HL + ex * ac + ez * as - EPS) return false;   // trục tiến
83	   if (Math.abs(dx * s + dz * c) >= HW + ex * as + ez * ac - EPS) return false;   // trục ngang
84	   return true;
85	 }
86	+/* Độ lấn của thân xe vào vật cản sol (m, ≤ 0 là không chồng): hộp lấy độ chồng nhỏ nhất trên 4 trục tách (SAT);
87	+   tròn lấy r − khoảng cách từ tâm tròn tới thân xe (tâm tròn nằm trong thân xe thì r + khoảng tới cạnh gần nhất). Chỉ dùng cho đường thoát */
88	+function drPenSolid(sol: DrSolid, x: number, z: number, c: number, s: number): number {
89	+  const ac = Math.abs(c), as = Math.abs(s);
90	+  if (sol.kind === 'circle') {
91	+    const dx = sol.cx - x, dz = sol.cz - z, lf = dx * c - dz * s, ln = dx * s + dz * c;
92	+    const ef = Math.abs(lf) - HL, en = Math.abs(ln) - HW;
93	+    if (ef <= 0 && en <= 0) return sol.r - Math.max(ef, en);
94	+    const qf = ef > 0 ? ef : 0, qn = en > 0 ? en : 0;
95	+    return sol.r - Math.hypot(qf, qn);
96	+  }
97	+  const ex = (sol.x1 - sol.x0) / 2, ez = (sol.z1 - sol.z0) / 2, dx = (sol.x0 + sol.x1) / 2 - x, dz = (sol.z0 + sol.z1) / 2 - z;
98	+  return Math.min(ex + HL * ac + HW * as - Math.abs(dx), ez + HL * as + HW * ac - Math.abs(dz),
99	+    HL + ex * ac + ez * as - Math.abs(dx * c - dz * s), HW + ex * as + ez * ac - Math.abs(dx * s + dz * c));
100	+}
101	 /* Thân xe chồng hộp xe tự động b không (cùng tầng: chân hai xe chênh < chiều cao xe) */
102	 function drHitBox(b: DrBox, x: number, y: number, z: number, c: number, s: number): boolean {
103	   if (Math.abs(b.y - y) >= CAR.height) return false;
104	   const bc = Math.cos(b.yaw), bs = Math.sin(b.yaw), dx = b.x - x, dz = b.z - z;
105	   /* bốn trục tách: f1 = (c, −s), n1 = (s, c), f2 = (bc, −bs), n2 = (bs, bc); hình chiếu nửa hộp lên trục a là hl|f·a| + hw|n·a| */
106	   const ff = c * bc + s * bs, fn = c * bs - s * bc;                  // f1·f2, f1·n2
107	   const nf = s * bc - c * bs, nn = s * bs + c * bc;                  // n1·f2, n1·n2
108	   if (Math.abs(dx * c - dz * s) >= HL + b.hl * Math.abs(ff) + b.hw * Math.abs(fn) - EPS) return false;
109	   if (Math.abs(dx * s + dz * c) >= HW + b.hl * Math.abs(nf) + b.hw * Math.abs(nn) - EPS) return false;
110	   if (Math.abs(dx * bc - dz * bs) >= b.hl + HL * Math.abs(ff) + HW * Math.abs(nf) - EPS) return false;
111	@@ -93,57 +109,104 @@ export function drFits(net: DrNet, p: DrPose, boxes: DrBox[], nBoxes: number, ig
112	   const ix0 = Math.floor((p.x - R) / DRC), ix1 = Math.floor((p.x + R) / DRC), iz0 = Math.floor((p.z - Rz) / DRC), iz1 = Math.floor((p.z + Rz) / DRC);
113	   for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
114	     const list = g.cells.get(drKey(ix, iz));
115	     if (!list) continue;
116	     for (let i = 0; i < list.length; i++) { const o = sol[list[i]]; if (o.y1 > ya && o.y0 < yb && drHitSolid(o, p.x, p.z, c, s)) return false; }
117	   }
118	   for (let i = 0; i < nBoxes; i++) if (!ignore[i] && drHitBox(boxes[i], p.x, yRef, p.z, c, s)) return false;
119	   return true;
120	 }
121	 
122	+/* ===== Đường thoát ===== */
123	+/* Mức "tệ" của tư thế p không hợp lệ, ghi vào BAD_N, BAD_D:
124	+   BAD_N = số điểm mẫu (trong 9) không có mặt đường cùng tầng; BAD_D = tổng độ lấn (drPenSolid > 0) vào các vật cản tĩnh cùng khoảng cao độ.
125	+   Đường thoát nhận bước con khi cả hai không tăng: lấn theo SAT tăng ngay khi đi sâu thêm, và chỉ giảm sau khi vượt quá nửa vật cản,
126	+   nên từ chỗ chồng nông không bao giờ đi xuyên qua được; đi vào vật cản mới thì tổng tăng. */
127	+let BAD_N = 0, BAD_D = 0;
128	+function drBad(net: DrNet, p: DrPose): void {
129	+  const yRef = p.y, c = Math.cos(p.yaw), s = Math.sin(p.yaw);
130	+  let n = 0, d = 0;
131	+  for (let i = -1; i <= 1; i++) for (let j = -1; j <= 1; j++) {
132	+    const lf = i * HL, ln = j * HW;
133	+    if (Number.isNaN(drGround(net, p.x + lf * c + ln * s, p.z - lf * s + ln * c, yRef))) n++;
134	+  }
135	+  const ya = yRef + SIM.floor, yb = yRef + CAR.height, sol = net.solids, g = drGrid(net), big = g.big;
136	+  for (let i = 0; i < big.length; i++) { const o = sol[big[i]]; if (o.y1 > ya && o.y0 < yb) { const q = drPenSolid(o, p.x, p.z, c, s); if (q > 0) d += q; } }
137	+  const R = HL * Math.abs(c) + HW * Math.abs(s), Rz = HL * Math.abs(s) + HW * Math.abs(c);
138	+  const ix0 = Math.floor((p.x - R) / DRC), ix1 = Math.floor((p.x + R) / DRC), iz0 = Math.floor((p.z - Rz) / DRC), iz1 = Math.floor((p.z + Rz) / DRC);
139	+  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
140	+    const list = g.cells.get(drKey(ix, iz));
141	+    if (!list) continue;
142	+    for (let k = 0; k < list.length; k++) {
143	+      const i = list[k], o = sol[i];
144	+      /* vật cản phủ nhiều ô được gặp nhiều lần: chỉ cộng ở ô đầu tiên (ô thấp nhất) mà nó và khung bao thân xe cùng có */
145	+      if (!(o.y1 > ya && o.y0 < yb)) continue;
146	+      const cx0 = o.kind === 'circle' ? o.cx - o.r : o.x0, cz0 = o.kind === 'circle' ? o.cz - o.r : o.z0;
147	+      if (ix !== Math.max(ix0, Math.floor(cx0 / DRC)) || iz !== Math.max(iz0, Math.floor(cz0 / DRC))) continue;
148	+      const q = drPenSolid(o, p.x, p.z, c, s); if (q > 0) d += q;
149	+    }
150	+  }
151	+  BAD_N = n; BAD_D = d;
152	+}
153	+
154	 /* ===== Dời thân xe ===== */
155	 let IGN = new Uint8Array(16);                                        // hộp bỏ qua trong lượt drMove hiện tại
156	 const CUR: DrPose = { x: 0, y: 0, z: 0, yaw: 0 }, CAND: DrPose = { x: 0, y: 0, z: 0, yaw: 0 };
157	 let mNet: DrNet, mBoxes: DrBox[], mN = 0;                            // tham số của lượt drMove hiện tại (tránh truyền lại / tạo closure)
158	+let mEsc = false, mBadN = 0, mBadD = 0;                              // đang ở đường thoát (CUR không hợp lệ) và mức tệ của CUR
159	+const BAD_TOL = 1e-6;                                                // m — dung sai làm tròn khi so tổng độ lấn
160	 
161	-/* Thử đặt thân xe tại CAND (cao độ lấy lại theo mặt đường tại tâm); được thì chép sang CUR */
