166	-  const y = drGround(mNet, CAND.x, CAND.z, CUR.y);
167	-  if (Number.isNaN(y)) return false;
168	+  let y = drGround(mNet, CAND.x, CAND.z, CUR.y);
169	+  if (Number.isNaN(y)) { if (!mEsc) return false; y = CUR.y; }
170	   CAND.y = y;
171	-  if (!drFits(mNet, CAND, mBoxes, mN, IGN)) return false;
172	+  if (drFits(mNet, CAND, mBoxes, mN, IGN)) mEsc = false;
173	+  else {
174	+    if (!mEsc) return false;
175	+    const c = Math.cos(CAND.yaw), s = Math.sin(CAND.yaw);
176	+    for (let i = 0; i < mN; i++) if (!IGN[i] && drHitBox(mBoxes[i], CAND.x, y, CAND.z, c, s)) return false;
177	+    drBad(mNet, CAND);
