182	   return true;
183	 }
184	 /* Bước con kiểu xe đạp: trục sau đi sd theo hướng giữa bước, xe xoay sy; tâm = trục sau + AX theo hướng mới */
185	 function drTryArc(sd: number, sy: number): boolean {
186	   const y0 = CUR.yaw, ym = y0 + sy / 2, y1 = y0 + sy;
187	   const rx = CUR.x - AX * Math.cos(y0) + sd * Math.cos(ym), rz = CUR.z + AX * Math.sin(y0) - sd * Math.sin(ym);
188	   CAND.x = rx + AX * Math.cos(y1); CAND.z = rz - AX * Math.sin(y1); CAND.yaw = y1;
189	   return drTry();
190	 }
191	 function drTryShift(dx: number, dz: number): boolean {
192	   CAND.x = CUR.x + dx; CAND.z = CUR.z + dz; CAND.yaw = CUR.yaw;
193	   return drTry();
